const rows = $input.all().map(i => i.json);
const THRESHOLD = 0.05; // 5 п.п. — см. README, честная оговорка про run-over-run вместо day-over-day

if (rows.length === 0 || Number(rows[0].snapshot_count) < 2) {
  return [{ json: { skip: true, message: 'Data Drift Monitor: первый снепшот, базы для сравнения ещё нет.' } }];
}

const drifted = rows.filter(r => Math.abs(Number(r.delta)) >= THRESHOLD);
if (drifted.length === 0) {
  return [{ json: { skip: true, message: 'Data Drift Monitor: отклонений выше порога не найдено.' } }];
}

const fmtPct = v => `${Math.round(Number(v) * 100)}%`;
const lines = drifted.map(r => {
  const label = r.metric_name === 'category_pct' ? r.metric_key : r.metric_key + ' (' + r.metric_name + ')';
  const isPctMetric = r.metric_name !== 'avg_confidence';
  const from = isPctMetric ? fmtPct(r.previous_value) : Number(r.previous_value).toFixed(2);
  const to = isPctMetric ? fmtPct(r.current_value) : Number(r.current_value).toFixed(2);
  return `${label}:\n${from} \u2192 ${to}`;
});
const message = ['\u26a0\ufe0f Data Drift', '', ...lines].join('\n\n');
return [{ json: { skip: false, message } }];
